import{_ as a,c as e,o as t,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"44、【姤】 巽下乾上","description":"子夏易傳 - 44、【姤】 巽下乾上","frontmatter":{"title":"44、【姤】 巽下乾上","description":"子夏易傳 - 44、【姤】 巽下乾上"},"headers":[],"relativePath":"classics/zixia/046.md","filePath":"classics/zixia/046.md"}'),i={name:"classics/zixia/046.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_44、【姤】-巽下乾上" tabindex="-1">44、【姤】 巽下乾上 <a class="header-anchor" href="#_44、【姤】-巽下乾上" aria-label="Permalink to “44、【姤】 巽下乾上”">​</a></h1><p>卦辭：姤，女壯，勿用取女。</p><p>彖曰：姤，遇也。柔遇剛也。勿用取女，不可與長也。天地相遇，品物鹹章也。剛遇中正，天下大行也。姤之時義大矣哉。</p><p>子夏：陽也，君人之道也，正之恆也。而陰來代之，眾以求之，其道遇也。陰之賊也。遇而合之，仕無正也。女之壯也，非人倫之道，不足以娶之。事無恆，不足以為用。夫易無窮也。陽不能獨化，化不可以無遇，故遇而後成。初茍而終固，即遂其生，化之大焉。且物無大也，無細也。其得之大遇也。待於外之來也，豈已之由乎。其在於遇人，大吉。則乾陽也，巽陰也，有天地相遇之道焉。天地遇而萬物章也，剛得中正而能擇其柔，聖人遇於大位也。則其道大行，君子遇於時，輔聖人之功而天下治也。品物得遇而其道乃通始，微而終著也。</p><p>象曰：天下有風，姤。後以施命誥四方。</p><p>子夏：人之治者，火承上之風，能君天下者，得天下之治也。施命告四方，人承其命，鹹得其遇也。</p><p>初六，繫於金柅，貞吉。有攸往，見兇。羸豕孚蹢躅。</p><p>象曰：繫於金柅，柔道牽也。</p><p>子夏：陰之為道，冝牽於陽。而守其正，保其吉也。君子隨遇而往，無永正，何以終乎，兇其冝也。無異於牝豕從豭，遇無信蹢躅而已。非久之道也。</p><p>九二，包有魚，無咎。不利賔。</p><p>象曰：包有魚，義不及賔也。</p><p>子夏：陰者，身之資也。魚非食之珍者。初非陰之正者，卦無陰，亦眾之所向也。已得之而供其求，眾失之，未足深吝，故獲之無咎。得其中者也。畜非正之物，懼人之見，其義豈及於賔哉。</p><p>九三，臀無膚，其行次且，厲無大咎。</p><p>象曰：其行次且，行未牽也。</p><p>子夏：求初之，合二已，得矣，胡獲焉。坐而不安，行而不正，牽繫其柔而未得也。以其不獲也。而止於位，故免於爭競之患雖，危而無大咎也。</p><p>九四，包無魚，起兇。</p><p>象曰：無魚之兇，逺民也。</p><p>子夏：無位之陰，遇斯獲矣，二有之也。應何為乎起已求，遇之兇之道也。</p><p>九五，以杞包瓜，含章，有隕自天。</p><p>象曰：九五含章，中正也。有隕自天，志不舎命也。</p><p>無中正之徳者，皆無魚以至於悔也。至五徳博而位尊，謀其道不思其欲，故食杞匏瓜而已。夫以剛正之體，含章明之徳，志在行道不舎敎令，如天降之也。莫不鹹賴矣，所謂剛遇中正而天下大行也。</p><p>上九，姤其角，吝，無咎。</p><p>象曰：姤其角，上窮。吝也。</p><p>子夏：已過體矣，何所遇乎，姤於角也。以是求遇，可惜者也。不至於爭，無吝已矣。</p>',24)])])}const m=a(i,[["render",r]]);export{f as __pageData,m as default};
